class AdminReports extends StatefulWidget { const AdminReports({super.key}); @override State<AdminReports> createState()=>_AdminReportsState(); }
class _AdminReportsState extends State<AdminReports>{int tab=0;
 @override Widget build(BuildContext context)=>SafeArea(child:StreamBuilder<List<AppUser>>(stream:FirestoreService().allUsers(),builder:(context,uSnap)=>StreamBuilder<List<Expense>>(stream:FirestoreService().allExpenses(),builder:(context,eSnap){final users=uSnap.data??[];final all=eSnap.data??[];final list=_filter(all);final total=list.fold<double>(0,(s,e)=>s+e.amount);return SingleChildScrollView(padding:const EdgeInsets.fromLTRB(20,24,20,120),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const PageTitle(title:'Global reports',subtitle:'All user expenses, grouped by time.'),const SizedBox(height:22),_tabs(),const SizedBox(height:16),Container(width:double.infinity,padding:const EdgeInsets.all(22),decoration:BoxDecoration(gradient:const LinearGradient(colors:[AppColors.ink,Color(0xFF1E3A8A)]),borderRadius:BorderRadius.circular(24)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(_label(),style:const TextStyle(color:Colors.white60,fontSize:13)),const SizedBox(height:7),Text('₹${NumberFormat('#,##0.00').format(total)}',style:const TextStyle(color:Colors.white,fontSize:31,fontWeight:FontWeight.w800)),const SizedBox(height:6),Text('${list.length} transactions • ${_userCount(list)} users',style:const TextStyle(color:Colors.white60,fontSize:12.5))])),const SizedBox(height:16),const BannerAdWidget(),const SizedBox(height:24),const Text('Expense activity',style:TextStyle(fontSize:18,fontWeight:FontWeight.w800)),const SizedBox(height:12),if(list.isEmpty)const EmptyState(title:'No expenses found',message:'There are no expenses for the selected period.') else ...list.map((e)=>ExpenseTile(expense:e,userName:_userName(users,e.userId))),]));})));
 Widget _tabs()=>Container(padding:const EdgeInsets.all(4),decoration:BoxDecoration(color:const Color(0xFFEFF3F8),borderRadius:BorderRadius.circular(15)),child:Row(children:List.generate(3,(i){final l=['Today','This Week','This Month'][i];return Expanded(child:GestureDetector(onTap:()=>setState(()=>tab=i),child:AnimatedContainer(duration:const Duration(milliseconds:180),padding:const EdgeInsets.symmetric(vertical:12),decoration:BoxDecoration(color:tab==i?Colors.white:Colors.transparent,borderRadius:BorderRadius.circular(12)),child:Text(l,textAlign:TextAlign.center,style:TextStyle(fontSize:12.5,fontWeight:tab==i?FontWeight.w800:FontWeight.w600,color:tab==i?AppColors.primary:AppColors.slate)))));})));
 List<Expense> _filter(List<Expense>x){final n=DateTime.now();if(tab==0)return x.where((e)=>e.expenseDate.year==n.year&&e.expenseDate.month==n.month&&e.expenseDate.day==n.day).toList();if(tab==1){final s=DateTime(n.year,n.month,n.day).subtract(Duration(days:n.weekday-1));return x.where((e)=>!e.expenseDate.isBefore(s)&&e.expenseDate.isBefore(s.add(const Duration(days:7)))).toList();}return x.where((e)=>e.expenseDate.year==n.year&&e.expenseDate.month==n.month).toList();}
 String _label()=>['Today','Current week','Current month'][tab];int _userCount(List<Expense>x)=>x.map((e)=>e.userId).toSet().length;String _userName(List<AppUser> users,String id){for(final u in users){if(u.uid==id)return u.name;}return 'User';}
}
